using System.Net;
using System.Text;
using Keynote.Midi;
using Keynote.Online;
namespace Keynote.Tests;
public class OnlineTests {
 [Fact] public async Task LibraryPersistsSuggestedOctaveAcrossReloads() { var dir=TempDir(); try { var lib=new MidiLibraryService(dir,new MidiImporter()); var bytes=await File.ReadAllBytesAsync(Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid")); var saved=await lib.AddAsync(bytes,Metadata with {RecommendedOctave=-1},CancellationToken.None); Assert.Equal(-1,saved.Entry.RecommendedOctave); var reloaded=Assert.Single(await new MidiLibraryService(dir,new MidiImporter()).ListAsync(CancellationToken.None)); Assert.Equal(-1,reloaded.RecommendedOctave); var duplicate=await lib.AddAsync(bytes,Metadata with {RecommendedOctave=1},CancellationToken.None); Assert.Equal(-1,duplicate.Entry.RecommendedOctave); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 sealed class Handler(Func<HttpRequestMessage,CancellationToken,Task<HttpResponseMessage>> handle) : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)=>handle(request,token); }
 static HttpClient Client(Func<HttpRequestMessage,CancellationToken,Task<HttpResponseMessage>> handle)=>new(new Handler(handle));
 static HttpResponseMessage Json(string json,HttpStatusCode code=HttpStatusCode.OK)=>new(code){Content=new StringContent(json,Encoding.UTF8,"application/json")};
 static string Fixture=>Path.Combine(AppContext.BaseDirectory,"Fixtures","test-c-major-scale.mid");
 static CatalogResult Metadata=>new("MIDIsss","1","Scale","Unknown","","Personal","https://midisss.com/api.php?action=get_midi&id=1");
 static string TempDir()=>Path.Combine(Path.GetTempPath(),"keynote-test-"+Guid.NewGuid().ToString("N"));
 [Fact] public async Task CatalogParsesDeduplicatesAndEncodesQuery() { string? uri=null; using var http=Client((r,t)=>{uri=r.RequestUri!.AbsoluteUri; return Task.FromResult(Json("[{\"id\":1,\"name\":\"Tune\",\"notes\":\"arrangement\"},{\"id\":1,\"name\":\"duplicate\"}]"));}); var provider=new MidisssCatalogProvider(http); var page=await provider.SearchAsync("Bach & friends",0,CancellationToken.None); Assert.Single(page.Results); Assert.Equal("Tune",page.Results[0].Title); Assert.Contains("%26",uri!); Assert.False(page.HasMore); Assert.Contains("id=1",provider.DownloadUri(page.Results[0]).Query); }
 [Fact] public async Task MutopiaFeedSearchUsesOnlyOfficialPieceLinksAndLabelsLicense() { const string xml="<rss><channel><item><title>Mozart: Minuet</title><link>http://www.mutopiaproject.org/cgibin/piece-info.cgi?id=42</link><description>Piano</description></item><item><title>Mozart malicious</title><link>http://127.0.0.1/cgibin/piece-info.cgi?id=1</link></item></channel></rss>"; using var http=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(xml)})); var provider=new MutopiaRecentProvider(http); var page=await provider.SearchAsync("mozart",0,CancellationToken.None); var result=Assert.Single(page.Results); Assert.Equal("https://www.mutopiaproject.org/cgibin/piece-info.cgi?id=42",result.SourceUrl); Assert.Contains("Creative Commons",result.License); Assert.Throws<NotSupportedException>(()=>provider.DownloadUri(result)); }
 [Fact] public async Task MutopiaRejectsDtd() { const string xml="<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///secret'>]><rss><channel><item><title>&x;</title></item></channel></rss>"; using var http=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(xml)})); await Assert.ThrowsAnyAsync<Exception>(()=>new MutopiaRecentProvider(http).SearchAsync("x",0,CancellationToken.None)); }
 [Fact] public async Task MutopiaPublicCatalogueParsesLicenseMidiAndPagination() { const string html="<table class='table-bordered result-table'><tr><td>Minuet</td><td>by J. S. Bach</td><td>BWV 1</td><td></td></tr><tr><td>for Piano</td><td>18th C.</td><td>Baroque</td><td></td></tr><tr><td>Edition</td><td><a href='../legal.html#pd'>Public Domain</a></td><td><a href='piece-info.cgi?id=42'>More Information</a></td><td>2005</td></tr><tr><td><a href='https://www.mutopiaproject.org/ftp/Bach/song.mid'>.mid file</a></td></tr></table><a href='make-table.cgi?startat=10&amp;searchingfor=bach'>Next 10</a>"; using var http=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(html)})); var provider=new MutopiaCatalogProvider(http); var page=await provider.SearchAsync("Bach",0,CancellationToken.None); var item=Assert.Single(page.Results); Assert.Equal("Public Domain",item.License); Assert.Contains("Bach",item.Artist); Assert.True(page.HasMore); Assert.Equal("/ftp/Bach/song.mid",provider.DownloadUri(item).AbsolutePath); }
 [Fact] public async Task MutopiaCatalogueRejectsPrivateDownloadAndUnknownMarkup() { const string html="<table class='result-table'><tr><td>Song</td><td>Artist</td></tr><tr><td>Piano</td></tr><tr><td>Edition</td><td>Public Domain</td><td><a href='piece-info.cgi?id=3'>More</a></td></tr><tr><td><a href='https://127.0.0.1/x.mid'>.mid</a></td></tr></table>"; using var http=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(html)})); var provider=new MutopiaCatalogProvider(http); var item=Assert.Single((await provider.SearchAsync("x",0,CancellationToken.None)).Results); Assert.Null(item.DirectUrl); Assert.Throws<NotSupportedException>(()=>provider.DownloadUri(item)); using var bad=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("<html>changed</html>")})); await Assert.ThrowsAsync<InvalidDataException>(()=>new MutopiaCatalogProvider(bad).SearchAsync("x",0,CancellationToken.None)); }
 [Fact] public async Task SearchFailureAndUnsupportedPaginationAreReported() { using var http=Client((r,t)=>Task.FromResult(Json("{}",HttpStatusCode.ServiceUnavailable))); var provider=new MidisssCatalogProvider(http); await Assert.ThrowsAsync<HttpRequestException>(()=>provider.SearchAsync("x",0,CancellationToken.None)); await Assert.ThrowsAsync<NotSupportedException>(()=>provider.SearchAsync("x",1,CancellationToken.None)); }
 [Fact] public async Task SearchCancellationStopsRequest() { using var http=Client(async (r,t)=>{await Task.Delay(Timeout.Infinite,t); return Json("[]");}); var provider=new MidisssCatalogProvider(http); using var cts=new CancellationTokenSource(); var task=provider.SearchAsync("x",0,cts.Token); cts.Cancel(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>task); }
 [Fact] public async Task DownloadAcceptsMidiAndRejectsInvalidAndUnsafeUrls() { var bytes=await File.ReadAllBytesAsync(Fixture); using var http=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)})); var downloader=new MidiDownloadService(http); Assert.Equal(bytes,await downloader.DownloadAsync(new Uri("https://midisss.com/api.php?action=get_midi&id=1"),null,CancellationToken.None)); await Assert.ThrowsAsync<InvalidOperationException>(()=>downloader.DownloadAsync(new Uri("http://127.0.0.1/x"),null,CancellationToken.None)); using var bad=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("not a midi")})); await Assert.ThrowsAsync<InvalidDataException>(()=>new MidiDownloadService(bad).DownloadAsync(new Uri("https://midisss.com/x"),null,CancellationToken.None)); }
 [Fact] public async Task DownloadRejectsOversizedAndRedirectResponses() { using var http=Client((r,t)=> { var result=new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(new byte[1])}; result.Content.Headers.ContentLength=MidiDownloadService.MaxBytes+1; return Task.FromResult(result); }); await Assert.ThrowsAsync<InvalidDataException>(()=>new MidiDownloadService(http).DownloadAsync(new Uri("https://midisss.com/x"),null,CancellationToken.None)); using var redirect=Client((r,t)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.Redirect))); await Assert.ThrowsAsync<HttpRequestException>(()=>new MidiDownloadService(redirect).DownloadAsync(new Uri("https://midisss.com/x"),null,CancellationToken.None)); }
 [Fact] public async Task DownloadCancellationIsPropagated() { using var http=Client(async (r,t)=>{await Task.Delay(Timeout.Infinite,t); return Json("{}");}); using var cts=new CancellationTokenSource(); var task=new MidiDownloadService(http).DownloadAsync(new Uri("https://midisss.com/x"),null,cts.Token); cts.Cancel(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>task); }
 [Fact] public async Task LibraryValidatesPersistsDeduplicatesAndRecoversMetadata() { var dir=TempDir(); try { var data=await File.ReadAllBytesAsync(Fixture); var lib=new MidiLibraryService(dir,new MidiImporter()); var first=await lib.AddAsync(data,Metadata,CancellationToken.None); Assert.False(first.Duplicate); var second=await lib.AddAsync(data,Metadata,CancellationToken.None); Assert.True(second.Duplicate); Assert.Equal(first.Entry.Sha256,second.Entry.Sha256); var fresh=new MidiLibraryService(dir,new MidiImporter()); Assert.Single(await fresh.ListAsync(CancellationToken.None)); var path=await fresh.OpenAsync(first.Entry,CancellationToken.None); Assert.Equal(8,new MidiImporter().Import(path).Notes.Count()); await File.WriteAllTextAsync(Path.Combine(dir,first.Entry.Sha256+".json"),"{"); var recovered=Assert.Single(await fresh.ListAsync(CancellationToken.None)); Assert.Contains("Recovered",recovered.Title); await File.WriteAllTextAsync(path,"modified"); await Assert.ThrowsAsync<InvalidDataException>(()=>fresh.OpenAsync(recovered,CancellationToken.None)); File.Delete(path); Assert.Single(await fresh.ListAsync(CancellationToken.None)); await Assert.ThrowsAsync<FileNotFoundException>(()=>fresh.OpenAsync(recovered,CancellationToken.None)); await fresh.RemoveAsync(recovered,CancellationToken.None); Assert.Empty(await fresh.ListAsync(CancellationToken.None)); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task LibraryRejectsMalformedMidiAndMissingFile() { var dir=TempDir(); try { var lib=new MidiLibraryService(dir,new MidiImporter()); var data="MThdBAD FILE CONTENT"u8.ToArray(); await Assert.ThrowsAnyAsync<Exception>(()=>lib.AddAsync(data,Metadata,CancellationToken.None)); var entry=new LibraryEntry(new string('a',64),"missing","","","","",DateTimeOffset.UtcNow); await Assert.ThrowsAsync<FileNotFoundException>(()=>lib.OpenAsync(entry,CancellationToken.None)); } finally { if(Directory.Exists(dir))Directory.Delete(dir,true); } }
 [Fact] public async Task OpennanSubmitAndPollingUseDocumentedEndpoints() { var requests=new List<string>(); using var http=Client(async(r,t)=>{ requests.Add(r.Method+" "+r.RequestUri!.AbsolutePath); if(r.Method==HttpMethod.Post) { var body=await r.Content!.ReadAsStringAsync(t); Assert.Contains("name=search",body); return Json("{\"id\":\"job_123\"}",HttpStatusCode.Accepted); } return Json("{\"status\":\"succeeded\",\"stage\":\"done\",\"progress\":100}"); }); var provider=new OpennanProvider(http); var id=await provider.SubmitAsync("search","Bach",null,CancellationToken.None); var result=await TranscriptionJobRunner.WaitAsync(provider,id,null,CancellationToken.None,TimeSpan.Zero); Assert.Equal("succeeded",result.Status); Assert.Equal("/v1/piano/transcriptions/job_123/midi",provider.DownloadUri(id).AbsolutePath); Assert.Equal(2,requests.Count); }
 [Fact] public async Task OpennanUploadsOnlyTheSelectedFileName() { var dir=TempDir(); Directory.CreateDirectory(dir); var path=Path.Combine(dir,"audio.wav"); try { await File.WriteAllBytesAsync(path,new byte[]{1,2,3}); using var http=Client(async(r,t)=>{ var body=await r.Content!.ReadAsStringAsync(t); Assert.Contains("name=file",body); Assert.Contains("audio.wav",body); Assert.DoesNotContain(dir,body); return Json("{\"id\":\"job_1\"}",HttpStatusCode.Accepted); }); Assert.Equal("job_1",await new OpennanProvider(http).SubmitAsync("file",null,path,CancellationToken.None)); } finally { Directory.Delete(dir,true); } }
 [Fact] public async Task OpennanReportsRateLimitAndRejectsUnsafeIds() { using var http=Client((r,t)=> { var response=Json("{}",HttpStatusCode.TooManyRequests); response.Headers.RetryAfter=new System.Net.Http.Headers.RetryConditionHeaderValue(TimeSpan.FromSeconds(30)); return Task.FromResult(response); }); var provider=new OpennanProvider(http); var ex=await Assert.ThrowsAsync<HttpRequestException>(()=>provider.GetStatusAsync("job_1",CancellationToken.None)); Assert.Contains("429",ex.Message); Assert.Throws<InvalidDataException>(()=>provider.DownloadUri("../private")); }
 [Fact] public void InspectorUsesNormalizedNotesAndTracks() { var report=new MidiInspector(new MidiImporter()).Inspect(Fixture); Assert.Equal(8,report.Song.Notes.Count()); Assert.Single(report.Tracks); Assert.True(report.PianoCandidate); Assert.Equal(60,report.MinPitch); Assert.Equal(72,report.MaxPitch); }
 [Fact] public async Task OpennanReportsFailureAndRejectsPrivateUrls() { using var http=Client((r,t)=>Task.FromResult(Json("{\"status\":\"failed\",\"error\":{\"message\":\"failed job\"}}"))); var provider=new OpennanProvider(http); var error=await Assert.ThrowsAsync<InvalidOperationException>(()=>TranscriptionJobRunner.WaitAsync(provider,"job1",null,CancellationToken.None,TimeSpan.Zero)); Assert.Contains("failed job",error.Message); await Assert.ThrowsAsync<ArgumentException>(()=>provider.SubmitAsync("url","https://127.0.0.1/private",null,CancellationToken.None)); await Assert.ThrowsAsync<ArgumentException>(()=>provider.SubmitAsync("search","http://localhost/x",null,CancellationToken.None)); }
 [Fact] public async Task OpennanPollingCancellationDoesNotRequireNetwork() { using var http=Client((r,t)=>Task.FromResult(Json("{\"status\":\"running\"}"))); using var cts=new CancellationTokenSource(); var task=TranscriptionJobRunner.WaitAsync(new OpennanProvider(http),"job1",null,cts.Token,TimeSpan.FromSeconds(10)); cts.Cancel(); await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>task); }
}
